    m41 = reach_with(BACKLOG, "there are now **four** unwatched shards",
                     "there are now **three** unwatched shards")
    m42 = reach_with(BACKLOG, "`SESSION_NOTES-S227-through-S225.md` (790 lines)", "")

    # --- Sub-clause fixtures. An adversarial review of THIS file measured that L8/forbidden,
    #     L8/set, L5/2's shape arm, L9's no-add-commit arm and L8's unreadable arm were each
    #     reachable by no mutant above — the defect this session had just diagnosed in its own
    #     ancestor's L5/2 and written into CLAUDE.md as a rule. These are that rule applied to me.
    m43 = dict(reach)                                    # CLAUDE.md: table intact, count words stale
    m43[CLAUDE] = (m43[CLAUDE]
                   .replace("**Trimmed four times (Sessions 222, 224, 228, 231):**",
                            "**Trimmed three times (Sessions 222, 224, 228):**", 1)
                   .replace("Retired records live in **four** write-once shards",
                            "Retired records live in **three** write-once shards", 1)
                   .replace("grep *all four*", "grep *all three*", 1)
                   .replace("there are FOUR, and a lookup must consult all of them",
                            "there are THREE, and a lookup must consult all of them", 1))
    # forbidden ALONE: the required string stays, the falsified one comes back beside it.
    m44 = reach_with(CONVENTIONS, "**Four instances so far**",
                     "**Four instances so far** — it said **Three instances so far** before this cut")
    # set ALONE: an ANCESTOR's name typo'd, so required and forbidden are both untouched.
    m45 = reach_with(CONVENTIONS, "`SESSION_NOTES-S224-through-S221.md` (Session 228",
                     "`SESSION_NOTES-S224-through-S220.md` (Session 228")
    # set, via the lookahead: drop an ancestor's own repo-map line and leave its `.verify.sh` line.
    m46 = reach_with(README,
                     "  SESSION_NOTES-S224-through-S221.md    # frozen SESSION_NOTES records, Sessions 224->221 (grep it; do not Read it)\n",
                     "")
    # L9's third arm: git knows the file but no commit that added it.
    m48 = tuple((p, None, d) if i == 0 else (p, c, d)
                for i, (p, c, d) in enumerate(lineage))
    # L8's unreadable arm.
    m49 = {k: v for k, v in reach.items() if k != README}
    m49[README] = None
    # required ALONE: a declared string reworded so no forbidden string appears and the shard
    # name set stays complete. Without this, nothing is caught by L8/required and nothing else.
    m50 = reach_with(CONVENTIONS, "**Four instances so far**", "**4 instances so far**")

    # --- L9 fixtures. Same shape as L7's, one level out: the ANCESTOR shards on disk.
    def lineage_with(idx, mutate):
        out = list(lineage)
        path, committed, on_disk = out[idx]
        out[idx] = (path, committed, mutate(on_disk))
        return tuple(out)
    m35 = lineage_with(0, lambda t: t[:20000])
    m36 = lineage_with(1, lambda _t: MISSING)
    m37 = lineage_with(2, lambda t: t.replace("e", "3", 1))

    SAME = object()          # the mutant's own shard, i.e. an untampered working tree
