        ("M15 substitution 3's anchor absent from `before` (declaration gone stale)",
         before.replace(FRONT_SUBST[2][0], "REPLACED BY AN EARLIER EDIT\n", 1), after, shard,
         claude, None, SAME, reach, lineage),
        ("M16 cut shifted: the oldest RETAINED record moved into the shard", before,
