    bad = []
    for name, b, a, s, c, decl, disk, rch, lin in mutants:
        # A mutant that does not name a disk state gets an untampered one: its own shard.
        d = s if disk is SAME else disk
        # The REAL sha, never a stand-in: L5/4 reads the ancestor shards through it, and a fake
        # one makes every one of them unreadable — which would "catch" every mutant by breaking
        # the proof rather than by detecting the mutation. L7 and L9 stay reachable regardless
        # because their applicability comes from `d` and `lin`, not from `sha`.
        fails, _ = check(b, a, s, c, sha, d, rch, lin, decl)
        if not fails:
            bad.append(name)
            print("  SURVIVED  %s" % name)
        else:
            # EVERY assertion that fires, not just the first: it must stay visible which assertion
            # is doing the work. A reader who thinks L3 is an independent second opinion on L1 is
            # mistaken — and M16-M50 are the thirty-five that prove L4-L9 are not either.
            codes = sorted({f.split(":")[0].split(" (")[0] for f in fails})
            print("  caught    %-72s -> %s" % (name, ", ".join(codes)))
